"""Writes src/lib/countries.ts from phonenumbers — the same data Django validates with (D-048).

Run from frontend/ with the backend virtualenv:  ../backend/.venv/bin/python scripts/build-countries.py
"""

from pathlib import Path

import phonenumbers

rows = ", ".join(f'["{region}", {phonenumbers.country_code_for_region(region)}]' for region in sorted(phonenumbers.SUPPORTED_REGIONS))
Path("src/lib/countries.ts").write_text(
    "// Generated by scripts/build-countries.py from phonenumbers (D-048) — do not edit by hand.\n"
    "// [ISO 3166-1 alpha-2 region, international calling code]; display names come from Intl.DisplayNames.\n"
    f"export const COUNTRIES: readonly (readonly [string, number])[] = [{rows}];\n",
    encoding="utf-8",
)
print(f"src/lib/countries.ts: {len(phonenumbers.SUPPORTED_REGIONS)} regions (phonenumbers {phonenumbers.__version__})")
